formData.jsFunction:
def addError(response, key, msg) {
    if (response[key] == null) response[key] = msg
    else if (response[key] instanceof List) response[key] << msg
    else response[key] = [response[key], msg]
}

def checkArrayPermission(array, response, what) {
    if (array == null) return
    array.each {
        if (!it.permission) {
            addError(response, "revoke.permission", "Please select a Permission for " + what)
        }
    }
}

def validate(request, response = [:]) {

    if (request.containsKey("revoke")) {
        def userArray = request.revoke?.user
        def roleArray = request.revoke?.role
        def organizationArray = request.revoke?.organization
        if (userArray == null && roleArray == null && organizationArray == null) {
            addError(response, "revoke.user", "Please select a user/role/organization for revoke")
            return response
        }
        checkArrayPermission(userArray, response, "user. ")
        checkArrayPermission(roleArray, response, "role. ")
        checkArrayPermission(organizationArray, response, "organization. ")
    }
    if (request.containsKey("share")) {
        def userArray = request.share?.user
        def roleArray = request.share?.role
        def organizationArray = request.share?.organization

        if (userArray == null && roleArray == null && organizationArray == null) {
            addError(response, "revoke.user", "Please select a user/role/organization for  share")
            return response
        }
        checkArrayPermission(userArray, response, "user. ")
        checkArrayPermission(roleArray, response, "role. ")
        checkArrayPermission(organizationArray, response, "organization.")
    }
    if (!request.containsKey("share") && !request.containsKey("revoke")) {
        addError(response, "shareOrRevoke", "Please select the checkbox to share or revoke")
    }
    return response
}
